import {prepareLabels} from './network.js';
import {icon as uiIcon,brand,appShell,emptyState} from './ui.js';
import {stockLinesMarkup,readStockLines,wireStockLines} from './stock-lines.js';
import {configureWorkflows,workflowTabs,workflowNames,loadWorkflows,workflowPage,workflowDashboard,workflowAction,wireWorkflows} from './workflows.js';
import {configureOperations,preparation,agencies,dispatches,operationAction,wireOperations} from './operations.js';
const $=s=>document.querySelector(s),app=$('#app');
const state={me:null,tab:'dashboard',shipments:[],agencies:[],users:[],merchants:[],stats:null,queue:[],dispatches:[],cities:[],activeContainer:null,ledger:[],inventory:[],search:'',status:'',shipPage:0,shipPageSize:50,shipTotal:0,workflowBoot:null,workflowData:null,workflowDetail:null,shipCity:'',shipSource:'',shipMerchant:'',shipSort:'newest',selectedIds:new Set(),workflowFilters:{},inboxUnread:0};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('fr-MA',{style:'currency',currency:'MAD'}).format((Number(n)||0)/100);
const date=s=>s?new Intl.DateTimeFormat('fr-FR',{dateStyle:'medium',timeStyle:'short',timeZone:'Africa/Casablanca'}).format(new Date(s)):'—';
const status=s=>`<span class="pill ${esc(s)}">${esc(state.me?.statusLabels?.[s]||s)}</span>`;
const icon={dashboard:'◫',shipments:'▣',agencies:'↔',imports:'⇪',merchants:'♧',inventory:'▥',operations:'⌁',dispatches:'▤',users:'♙',finance:'¤',tracking:'⌕',driver:'▦'};
const tabs={dashboard:'Tableau de bord',shipments:'Colis',agencies:'Agences & hubs',imports:'Import Excel',merchants:'Marchands',inventory:'Stock & Fulfillment',operations:'Réception & préparation',dispatches:'Envois par ville',users:'Utilisateurs',finance:'COD & Finance',tracking:'Suivi public',driver:'Mes livraisons'};
Object.assign(tabs,workflowNames);for(const tab of Object.keys(workflowNames))icon[tab]=({pickups:'↥',returns:'↶',claims:'☷',arrivals:'⇣',routes:'⌘',cash:'¤',vehicles:'▰',adjustments:'±',notifications:'◉',settings:'⚙',audit:'≡'})[tab];
const can=permission=>state.me?.permissions.includes('*')||state.me?.permissions.includes(permission);
let shipSearchTimer,refreshSerial=0;
const clearSelection=()=>state.selectedIds.clear();
let toastTimer;function toast(message,bad=false){const e=$('#toast');e.textContent=message;e.classList.toggle('is-error',bad);e.style.background=bad?'#a42d43':'#153f3a';e.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('show'),bad?7000:3500);if(bad){const form=document.querySelector('.modal-backdrop:last-of-type form')||document.querySelector('#auth-form');if(form){let error=form.querySelector('.form-error');if(!error){error=document.createElement('div');error.className='form-error';error.setAttribute('role','alert');form.prepend(error);}error.textContent=message;error.scrollIntoView({block:'nearest'});}}}
async function api(path,{method='GET',data,raw,contentType}={}){
 const options={method,credentials:'same-origin',headers:{'X-Requested-With':'delivery-ui','X-TransitFlow-Origin':location.origin}};
 if(raw){options.body=raw;options.headers['Content-Type']=contentType||'application/octet-stream';}
 else if(data!==undefined){options.headers['Content-Type']='application/json';options.body=JSON.stringify(data);}
 const res=await fetch('/api'+path,options);
 if(!res.ok){if(res.status===401&&state.me){state.me=null;authPage();}let e;try{e=(await res.json()).error;}catch{}throw Error(e||`Erreur HTTP ${res.status}`);}
 if(res.headers.get('content-type')?.includes('spreadsheetml'))return {file:await res.blob(),filename:(res.headers.get('content-disposition')?.match(/filename="([^"]+)"/)||[])[1]||'colis.xlsx'};
 return res.json();
}
const field=(label,name,opts={})=>`<div class="field"><label for="${name}">${esc(label)}</label>${opts.options?`<select name="${name}" id="${name}" ${opts.required?'required':''}>${opts.options.map(x=>`<option value="${esc(x.value)}">${esc(x.label)}</option>`).join('')}</select>`:`<input id="${name}" name="${name}" type="${opts.type||'text'}" ${opts.type==='password'?'minlength="12" maxlength="128"':''} placeholder="${esc(opts.placeholder||'')}" ${opts.required?'required':''} ${opts.min!==undefined?`min="${opts.min}"`:''} ${opts.step?`step="${opts.step}"`:''} ${opts.value!==undefined?`value="${esc(opts.value)}"`:''} ${opts.autocomplete?`autocomplete="${opts.autocomplete}"`:''}>`}</div>`;
const formData=el=>Object.fromEntries(new FormData(el));
function authPage(setup=false){
 app.innerHTML=`<div class="auth"><section class="auth-art"><div class="logo">${brand()}</div><div><p class="tiny" style="letter-spacing:3px;color:#94adf0;font-weight:800">GESTION DE LIVRAISON</p><h1>La livraison,<br>dans le bon sens.</h1><p>Un seul espace pour vos collectes, vos agences, vos livreurs et vos clients.</p></div><div class="auth-points"><span>Agences & hubs</span><span>Ramassage au scan</span><span>Envois par ville</span></div></section><main class="auth-main"><div class="auth-card"><span class="tag">ESPACE DE CONNEXION</span><h2 style="margin:22px 0 7px">${setup?'Bienvenue sur TransitFlow':'Ravi de vous retrouver'}</h2><p class="muted">${setup?'Créez une seule fois le profil de votre société et son administrateur.':'Connectez-vous avec votre email et votre mot de passe.'}</p><form id="auth-form" class="form">${setup?field('Nom de la société','companyName',{required:true,placeholder:'Ex. Atlas Livraison'})+field('Votre nom','fullName',{required:true}):''}${field('Adresse email','email',{type:'email',required:true,autocomplete:'email'})}${field('Mot de passe','password',{type:'password',required:true,placeholder:'12 caractères minimum',autocomplete:setup?'new-password':'current-password'})}<button class="btn" type="submit">${setup?'Configurer la société':'Se connecter'} →</button></form><p class="tiny muted" style="margin-top:25px">Les comptes de l’équipe et des marchands sont créés par l’administrateur.</p></div></main></div>`;
 $('#auth-form').addEventListener('input',()=>$('#auth-form .form-error')?.remove());
 $('#auth-form').addEventListener('submit',async e=>{e.preventDefault();const data=formData(e.target),button=e.target.querySelector('button');button.disabled=true;try{await api(setup?'/auth/setup':'/auth/login',{method:'POST',data});if(setup){toast('Société configurée. Connectez-vous.');authPage();}else await load();}catch(err){toast(err.message,true);button.disabled=false;}});
}
async function navigate(tab,{detail=null,replace=false}={}){
 if(!availableTabs().includes(tab))return;
 state.tab=tab;state.workflowDetail=detail;state.labelSelection=new Set();state.networkFeedback=null;clearSelection();
 const url=new URL(location.href);url.search='';url.searchParams.set('tab',tab);if(detail)url.searchParams.set('id',detail.id);if(tab==='shipments'&&state.search)url.searchParams.set('q',state.search);
 history[replace?'replaceState':'pushState']({},'',url);await refresh();document.querySelector('#main-content')?.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});
}
async function load(){
 try{
  const setup=await api('/auth/setup');if(setup.setupRequired)return authPage(true);
  const me=await api('/me');if(state.me?.user.id!==me.user.id){state.workflowBoot=null;state.workflowDetail=null;state.workflowFilters={};state.movementOffset=0;state.dashboardSummary=null;state.shipments=[];state.inventory=[];state.users=[];state.merchants=[];state.agencies=[];state.queue=[];state.dispatches=[];state.selectedIds.clear();state.search='';state.status='';state.shipCity='';state.shipSource='';state.shipMerchant='';}
  state.me=me;const params=new URLSearchParams(location.search);state.tab=params.get('tab')||'dashboard';if(!availableTabs().includes(state.tab))state.tab='dashboard';state.search=params.get('q')||'';state.status=params.get('status')||'';state.shipCity=params.get('city')||'';state.shipSource=params.get('source')||'';state.shipMerchant=params.get('merchantId')||'';state.shipSort=params.get('sort')||'newest';state.shipPage=Math.max(0,Number(params.get('page'))||0);
  state.workflowDetail=workflowTabs().includes(state.tab)&&/^[a-f0-9-]{36}$/.test(params.get('id')||'')?{kind:state.tab,id:params.get('id')}:null;await refresh();
 }catch(error){if(state.me){render();toast(error.message,true);}else{authPage();if(error.message!=='Connexion requise')toast(error.message,true);}}
}
async function refresh(){
 if(!state.me)return;const serial=++refreshSerial,current=()=>serial===refreshSerial&&Boolean(state.me);document.querySelector('#main-content')?.setAttribute('aria-busy','true');
 const assign=(key,value)=>{if(current())state[key]=value;};
 if(state.tab==='shipments'){const view=new URL(location.href);for(const [name,value] of Object.entries({tab:'shipments',q:state.search,status:state.status,city:state.shipCity,source:state.shipSource,merchantId:state.shipMerchant,sort:state.shipSort==='newest'?'':state.shipSort,page:state.shipPage||''})){if(value)view.searchParams.set(name,value);else view.searchParams.delete(name);}history.replaceState({},'',view);}
 const params=new URLSearchParams({limit:state.shipPageSize,offset:state.shipPage*state.shipPageSize,q:state.search,status:state.status,city:state.shipCity,source:state.shipSource,merchantId:state.shipMerchant,sort:state.shipSort});
 const role=state.me.user.role,fetches=[api('/shipments?'+params).then(x=>{assign('shipments',x.shipments);assign('shipTotal',x.total);}),api('/stats').then(x=>assign('stats',x)),api('/cities').then(x=>assign('cities',x.cities)),api('/workflow/notifications').then(x=>assign('inboxUnread',x.unread))];
 if(can('agencies')||can('dispatch'))fetches.push(api('/agencies').then(x=>assign('agencies',x.agencies)));
 if(can('users.read'))fetches.push(api('/users').then(x=>assign('users',x.users)));
 if(can('directory'))fetches.push(api('/merchants').then(x=>assign('merchants',x.merchants)));
 if(can('warehouse'))fetches.push(api('/operations/queue').then(x=>assign('queue',x.shipments)));
 if(can('dispatch')||can('dispatch.read'))fetches.push(api('/dispatches').then(x=>assign('dispatches',x.dispatches)));
 if(can('inventory.read'))fetches.push(api('/inventory').then(x=>assign('inventory',x.products)));
 if(role==='MERCHANT')fetches.push(api('/merchant/stock').then(x=>assign('inventory',x.products.map(p=>({...p,on_hand:p.onHand,merchant_id:state.me?.user.merchant_id})))));
 if(can('finance'))fetches.push(api('/ledger').then(x=>assign('ledger',x.entries)));
 try{await Promise.all(fetches);if(!current())return;await loadWorkflows(current);if(!current())return;state.selectedIds=new Set([...state.selectedIds].filter(id=>state.shipments.some(s=>s.id===id)));render();}finally{if(current())document.querySelector('#main-content')?.removeAttribute('aria-busy');}
}
const availableTabs=()=>{
 const allowed=['dashboard','shipments'];
 if(can('agencies'))allowed.push('agencies');if(can('directory'))allowed.push('merchants');if(can('imports'))allowed.push('imports');if(can('inventory.read'))allowed.push('inventory');if(can('warehouse'))allowed.push('operations');if(can('dispatch')&&!['AGENCY_MANAGER','AGENCY_AGENT'].includes(state.me.user.role))allowed.push('dispatches');if(can('*'))allowed.push('users');if(can('finance'))allowed.push('finance');return [...allowed,...workflowTabs(),'tracking'];
};
function render(){if(!state.me)return;const allowed=availableTabs();if(!allowed.includes(state.tab))state.tab=allowed[0];app.innerHTML=appShell({state,allowed,tabs,content:page(),esc});wire();}
function heading(title,sub,action=''){return `<div class="section-title"><div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`;}
function page(){if(workflowTabs().includes(state.tab))return workflowPage();if(state.tab==='dashboard')return workflowDashboard();switch(state.tab){case 'dashboard':return dashboard();case 'shipments':return shipments();case 'agencies':return agencies();case 'imports':return imports();case 'merchants':return merchants();case 'inventory':return inventory();case 'operations':return preparation();case 'dispatches':return dispatches();case 'users':return users();case 'finance':return finance();case 'tracking':return tracking();default:return dashboard();}}
function dashboard(){const s=state.stats||{total:0,byStatus:{},deliveredCodCentimes:0,agencies:0};const delivered=s.byStatus.DELIVERED||0;const pending=(s.byStatus.CREATED||0)+(s.byStatus.ASSIGNED_AGENCY||0)+(s.byStatus.EXPORTED||0);const cards=[['Total colis',s.total,'▣','Tous les statuts'],['Livraisons réussies',delivered,'✓',s.total?Math.round(100*delivered/s.total)+'% du total':'Aucun colis'],['En préparation',pending,'◷','À ramasser'],['COD livré',money(s.deliveredCodCentimes),'¤','Montant déclaré livré']];
 const chart=Object.entries(s.byStatus).sort((a,b)=>b[1]-a[1]);return `${heading('Vue d’ensemble','Suivez les opérations de votre société en un coup d’œil.',`<button class="btn" data-action="new-shipment">＋ Nouvelle commande</button>`)}<div class="grid cols4">${cards.map(c=>`<section class="card metric"><div style="display:flex;justify-content:space-between"><span class="metric-label">${c[0]}</span><span class="pict">${c[2]}</span></div><span class="metric-value">${c[1]}</span><span class="metric-foot">${c[3]}</span></section>`).join('')}</div><div class="grid cols2" style="margin-top:22px"><section class="card"><div class="headline"><h2>Répartition des statuts</h2><span class="tag">En direct</span></div>${chart.length?chart.map(([k,n])=>`<div class="chart-row"><span class="chart-label">${esc(state.me.statusLabels[k]||k)}</span><div class="bar-track"><div class="bar-fill" style="width:${Math.round(n/s.total*100)}%"></div></div><span class="chart-num">${n}</span></div>`).join(''):`<div class="empty">Aucune commande pour le moment.</div>`}</section><section class="card"><div class="headline"><h2>Réseau & opérations</h2></div><div class="subtle"><strong>${s.agencies} agences / hubs</strong><p class="muted tiny" style="margin:6px 0">Une agence de destination par ville ; tri contrôlé au scan.</p></div><div class="divider"></div><h3>Actions rapides</h3><div class="actions"><button class="btn outline" data-tab="agencies">Gérer les agences</button><button class="btn outline" data-tab="imports">Importer Excel</button><button class="btn outline" data-tab="shipments">Voir les colis</button></div><p class="tiny muted" style="margin-top:20px">Préparation → ramassage → tri dans le container de la ville → départ.</p></section></div><div class="card" style="margin-top:22px"><div class="headline"><h2>Dernières commandes</h2><button class="btn outline small" data-tab="shipments">Toutes les commandes →</button></div>${shipmentTable(state.shipments.slice(0,6))}</div>`;}
function merchantDashboard(){const sh=state.shipments,counts=state.stats?.byStatus||{},delivered=counts.DELIVERED||0,pending=['CREATED','AWAITING_PICKUP','COLLECTED','ASSIGNED_AGENCY','EXPORTED','HANDED_OVER','PICKED_UP','AT_AGENCY','IN_TRANSIT','OUT_FOR_DELIVERY','POSTPONED','UNREACHABLE'].reduce((n,status)=>n+(counts[status]||0),0);
 return `<div class="note" style="margin-bottom:16px;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px"><strong>Relevés des livraisons 24h, versements et stock détaillé</strong><a class="btn" href="/merchant.html">Ouvrir mon espace marchand complet →</a></div>${heading('Espace marchand',`Bienvenue ${esc(state.me.user.full_name)} · Gérez vos commandes et suivez vos livraisons.`,`<button class="btn" data-action="new-shipment">＋ Nouvelle commande</button>`)}
 <div class="grid cols3"><section class="card metric"><span class="metric-label">Mes commandes</span><span class="metric-value">${state.stats?.total||0}</span><span class="metric-foot">Commandes de mon magasin</span></section><section class="card metric"><span class="metric-label">Livrées</span><span class="metric-value">${delivered}</span><span class="metric-foot">Livraisons confirmées</span></section><section class="card metric"><span class="metric-label">À traiter / en transit</span><span class="metric-value">${pending}</span><span class="metric-foot">Suivez les statuts en direct</span></section></div>
 <section class="card" style="margin-top:20px"><div class="headline"><h2>Mes dernières commandes</h2><button class="btn small outline" data-tab="shipments">Voir toutes →</button></div>${shipmentTable(sh.slice(0,6))}</section><div class="note" style="margin-top:20px">Les demandes créées sont automatiquement rattachées à votre magasin. Les affectations des livreurs et des agences sont gérées par la société de livraison.</div>`;}
function shipmentActions(s){return `<button class="btn outline small ship-more" data-action="ship-actions" data-id="${esc(s.id)}" aria-label="Actions du colis ${esc(s.tracking)}">••• <span>Actions</span></button>`;}
function shipmentMenuContent(s){
 const op=['ADMIN','OPERATIONS'].includes(state.me.user.role),admin=state.me.user.role==='ADMIN';
 const done=['DELIVERED','RETURNED','RETURNED_MERCHANT','CANCELLED'].includes(s.status);
 const item=(action,label)=>`<button type="button" class="menu-option" data-action="${action}" data-id="${esc(s.id)}">${label}</button>`;
 return `<div class="shipment-options">${item('history','◉ Détails du suivi')}${item('info','ⓘ Information du colis')}
 ${op&&!done?item('edit-shipment','✎ Modifier le colis'):''}
 ${admin&&!done?item('change-cod','DH Changer le prix'):''}
 ${state.me.user.role!=='FINANCE'?`${item('print-ticket','▣ Imprimer Ticket')}${item('print-ticket','⇩ Imprimer E-Ticket / PDF')}`:''}
 ${op?item('prep-document',s.order_source==='STOCK'?'▥ Bon stock':'▤ Bon de livraison'):''}
 ${op?item('add-note','✦ Ajouter une remarque'):''}
 ${op?item('assign','↗ Affecter'):''}${can('claims.manage')||can('routes.manage')?item('wf-contact','☎ Contact / report'):''}${can('routes.manage')?(s.status==='LOST'?item('wf-recover','✓ Colis retrouvé'):item('wf-incident','⚑ Perte / dommage')):''}</div>`;
}
function shipmentTable(rows,selectable=false){
 if(!rows.length)return emptyState('Aucun colis trouvé','Modifiez vos filtres ou enregistrez une nouvelle commande.','shipments');
 const checkbox=s=>selectable?`<input type="checkbox" class="row-select" data-select-shipment="${esc(s.id)}" aria-label="Sélectionner ${esc(s.tracking)}" ${state.selectedIds.has(s.id)?'checked':''}>`:'';
 const payment=s=>Number(s.cod_centimes)===0?'Sans COD':s.cod_collected?'COD rapproché':'COD à rapprocher';
 return `<div class="table-scroll shipments-table"><table class="table"><thead><tr>${selectable?`<th class="select-cell"><input type="checkbox" id="ship-select-all" aria-label="Sélectionner les colis de cette page" ${rows.length&&rows.every(s=>state.selectedIds.has(s.id))?'checked':''}></th>`:''}<th>Colis / marchand</th><th>Destinataire</th><th>Destination</th><th>Statut de livraison</th><th class="text-right">Montant COD</th><th class="actions-col">Actions</th></tr></thead><tbody>${rows.map(s=>`<tr class="${state.selectedIds.has(s.id)?'selected':''}">${selectable?`<td class="select-cell">${checkbox(s)}</td>`:''}<td><div class="tracking-line"><button class="text-button code" data-action="history" data-id="${esc(s.id)}">${esc(s.tracking)}</button><button class="copy-button" data-action="copy-tracking" data-id="${esc(s.id)}" aria-label="Copier ${esc(s.tracking)}">${uiIcon('copy')}</button></div><small class="cell-sub">${esc(s.merchant_name||'Sans marchand')}<span class="source-chip">${s.order_source==='STOCK'?'Stock':'Externe'}</span></small></td><td><strong>${esc(s.recipient)}</strong><a class="cell-sub phone-link" href="tel:${esc(s.phone.replace(/[^+0-9]/g,''))}">${esc(s.phone)}</a></td><td><strong>${esc(s.city)}</strong><small class="cell-sub">${esc(s.driver_name||s.agency_name||'À affecter')}</small></td><td>${status(s.status)}${s.pending_agency_update?'<small class="sync-warning">Mise à jour agence attendue</small>':''}</td><td class="text-right"><strong class="amount">${money(s.cod_centimes)}</strong><small class="cell-sub">${payment(s)}</small></td><td>${shipmentActions(s)}</td></tr>`).join('')}</tbody></table></div><div class="mobile-colis">${rows.map(s=>`<article class="shipment-card ${state.selectedIds.has(s.id)?'selected':''}"><div class="shipment-card-top"><div class="mobile-tracking">${checkbox(s)}<button class="text-button code" data-action="history" data-id="${esc(s.id)}">${esc(s.tracking)}</button></div>${status(s.status)}</div><h3>${esc(s.recipient)}</h3><p class="mobile-destination">${esc(s.city)} <span>·</span> ${esc(s.merchant_name||'Sans marchand')}</p><div class="shipment-card-bottom"><strong class="amount">${money(s.cod_centimes)}<small>${payment(s)}</small></strong><div class="card-actions"><a class="icon-button" href="tel:${esc(s.phone.replace(/[^+0-9]/g,''))}" aria-label="Appeler ${esc(s.recipient)}">${uiIcon('phone')}</a>${shipmentActions(s)}</div></div></article>`).join('')}</div>`;
}
function shipments(){
 const activeFilters=[state.status,state.shipCity,state.shipSource,state.shipMerchant,state.search].filter(Boolean).length;
 const options=(id,label,values,value)=>`<label class="filter-field"><span>${label}</span><select id="${id}">${values.map(([key,text])=>`<option value="${esc(key)}" ${key===value?'selected':''}>${esc(text)}</option>`).join('')}</select></label>`;
 const counts=state.stats?.byStatus||{},chips=[['','Tous les colis',state.stats?.total||0],['CREATED','À imprimer',counts.CREATED||0],['AWAITING_PICKUP','Attente de ramassage',counts.AWAITING_PICKUP||0],['IN_TRANSIT','En transit',counts.IN_TRANSIT||0],['OUT_FOR_DELIVERY','En livraison',counts.OUT_FOR_DELIVERY||0],['DELIVERED','Livrés',counts.DELIVERED||0],['RETURNED','Retournés',counts.RETURNED||0]];
 return `${heading('Vos expéditions','Retrouvez chaque colis, son destinataire et son avancement.',can('imports')?`<button class="btn outline" data-tab="imports">${uiIcon('imports')}Importer des commandes</button>`:'')}<div class="list-tabs">${chips.map(([value,label,count])=>`<button data-action="ship-status-chip" data-value="${value}" class="${state.status===value?'active':''}">${label}<span>${count}</span></button>`).join('')}</div><section class="card data-panel"><div class="shipment-search-bar"><label class="search-control">${uiIcon('search')}<input id="ship-search" placeholder="Tracking, nom, téléphone ou ID…" aria-label="Rechercher dans les colis" value="${esc(state.search)}" autocomplete="off"></label><div class="actions"><label class="sort-control">Trier par<select id="ship-sort"><option value="newest" ${state.shipSort==='newest'?'selected':''}>Plus récents</option><option value="oldest" ${state.shipSort==='oldest'?'selected':''}>Plus anciens</option><option value="cod_desc" ${state.shipSort==='cod_desc'?'selected':''}>COD décroissant</option></select></label><button class="icon-button" data-action="refresh" aria-label="Actualiser les colis">${uiIcon('clock')}</button></div></div><div class="filter-bar">${options('ship-city','Destination',[['','Toutes les villes'],...state.cities.map(city=>[city,city])],state.shipCity)}${options('ship-status','Statut',[['','Tous les statuts'],...Object.entries(state.me.statusLabels)],state.status)}${options('ship-source','Origine',[['','Toutes les commandes'],['EXTERNAL','Colis externes'],['STOCK','Commandes stock']],state.shipSource)}${state.merchants.length?options('ship-merchant','Marchand',[['','Tous les marchands'],...state.merchants.map(m=>[m.id,m.name])],state.shipMerchant):''}${activeFilters?`<button class="text-button clear-filters" data-action="ship-reset">Réinitialiser ${uiIcon('close')}</button>`:''}</div><div class="selection-bar" ${state.selectedIds.size?'':'hidden'}><span><strong data-selected-count>${state.selectedIds.size}</strong> colis sélectionné(s)</span><div class="actions"><button class="btn small" data-action="ship-export">${uiIcon('download')}Exporter CSV</button><button class="btn small outline" data-action="ship-clear-selection">Annuler la sélection</button></div></div><div class="result-bar"><span><strong>${state.shipTotal}</strong> résultat${state.shipTotal>1?'s':''}</span><span>Sélection et export sur cette page</span></div>${shipmentTable(state.shipments,true)}<div class="table-footer"><label>Afficher <select id="ship-page-size">${[25,50,100].map(n=>`<option value="${n}" ${state.shipPageSize===n?'selected':''}>${n}</option>`).join('')}</select> par page</label><span>${state.shipTotal?state.shipPage*state.shipPageSize+1:0}–${Math.min((state.shipPage+1)*state.shipPageSize,state.shipTotal)} sur ${state.shipTotal}</span><div class="actions"><button class="btn outline small" data-action="ship-prev" ${state.shipPage===0?'disabled':''}>Précédent</button><button class="btn outline small" data-action="ship-next" ${(state.shipPage+1)*state.shipPageSize>=state.shipTotal?'disabled':''}>Suivant ${uiIcon('arrow')}</button></div></div></section>`;
}
function merchants(){return `${heading('Marchands','Comptes marchands et rattachement des commandes.',`${can('shipments')?'<button class="btn" data-action="new-merchant">＋ Nouveau marchand</button>':''}`)}<div class="grid cols3">${state.merchants.map(m=>`<div class="card partner-card"><span class="partner-icon">${esc(m.name.slice(0,1).toUpperCase())}</span><div><strong>${esc(m.name)}</strong><small>${esc(m.phone||'Aucun téléphone')}</small></div></div>`).join('')||`<div class="card empty">Aucun marchand. Créez votre premier marchand.</div>`}</div><p class="note" style="margin-top:20px">Le compte utilisateur « MERCHANT » doit être rattaché explicitement à un marchand. Il voit uniquement les commandes de son compte.</p>`;}
function imports(){return `${heading('Importer des commandes','CSV ou Excel XLSX (première feuille) · jusqu’à 1000 lignes par fichier.')}<div class="grid cols2"><section class="card"><div class="headline"><h2>Nouvel import</h2><span class="tag">CSV / XLSX</span></div><form id="import-form" class="form"><div class="field"><label for="import-file">Fichier de commandes</label><input id="import-file" type="file" accept=".xlsx,.csv" required></div><button class="btn" type="submit">⇪ Importer les commandes</button></form><div id="import-result" class="note" style="margin-top:17px">Les doublons de tracking sont ignorés et signalés. Chaque commande reste rattachée à votre société.</div></section><section class="card"><h2>Colonnes attendues</h2><p class="muted">Les noms de colonnes ci-dessous peuvent également être traduits avec les alias standards.</p><div class="table-scroll"><table class="table"><thead><tr><th>Colonne</th><th>Exemple</th></tr></thead><tbody>${[['Tracking','DN20260001'],['Destinataire','Client A'],['Téléphone','0612345678'],['Adresse','Quartier Salam'],['Ville','Agadir'],['COD','199.00'],['Description','1 colis']].map(x=>`<tr><td>${x[0]}</td><td>${x[1]}</td></tr>`).join('')}</tbody></table></div><p class="note">L’import n’affecte pas automatiquement les transporteurs : la sélection reste manuelle.</p></section></div>`;}
function inventory(){return `${heading('Stock & Fulfillment','Produits, réception de lots et réservation FIFO pour les commandes.',`<div class="actions"><button class="btn outline" data-action="assign-stock-owner">🏷️ Attribuer stock</button><button class="btn outline" data-tab="stock-intakes">Entrées & bons</button><button class="btn outline" data-action="receive-stock">Réception directe</button><button class="btn" data-action="new-product">＋ Produit</button></div>`)}<div class="grid cols3" style="margin-bottom:20px"><div class="card metric"><span class="metric-label">Références SKU</span><span class="metric-value">${state.inventory.length}</span></div><div class="card metric"><span class="metric-label">Stock disponible</span><span class="metric-value">${state.inventory.reduce((s,p)=>s+p.available,0)}</span></div><div class="card metric"><span class="metric-label">Unités réservées</span><span class="metric-value">${state.inventory.reduce((s,p)=>s+p.reserved,0)}</span></div></div><div class="card"><div class="headline"><h2>Produits en stock</h2><div class="actions"><button class="btn outline small" data-action="reserve-stock">Réserver pour un colis</button></div></div>${state.inventory.length?`<div class="table-scroll"><table class="table"><thead><tr><th>SKU</th><th>Produit</th><th>Physique</th><th>Réservé</th><th>Disponible</th><th>Quarantaine</th></tr></thead><tbody>${state.inventory.map(p=>`<tr><td class="code">${esc(p.sku)}</td><td>${esc(p.name)}</td><td>${p.on_hand}</td><td>${p.reserved}</td><td class="strong">${p.available}${p.available<=p.low_stock_threshold?' · Stock bas':''}</td><td>${p.quarantined||0}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">Ajoutez vos produits pour commencer le fulfillment.</div>`}<p class="note" style="margin-top:17px">Les réservations utilisent les lots les plus anciens en premier (FIFO). Contrôlez les produits et quantités avant le scan du colis. Les entrées, inventaires et mouvements sont accessibles dans Warehouse & stock.</p></div>`;}
function users(){return `${heading('Utilisateurs & rôles','Chaque livreur se connecte au même site avec son propre compte.',`<button class="btn" data-action="new-user">＋ Nouvel utilisateur</button>`)}<section class="card"><div class="table-scroll"><table class="table"><thead><tr><th>Nom</th><th>Email</th><th>Rôle</th><th>Actif</th><th>Actions</th></tr></thead><tbody>${state.users.map(u=>`<tr><td class="strong">${esc(u.full_name)}</td><td>${esc(u.email)}</td><td><span class="tag">${esc(state.me.roleLabels[u.role]||u.role)}</span></td><td>${u.active?'● Oui':'Non'}</td><td><button class="btn outline small" data-action="edit-user" data-id="${u.id}">Modifier</button></td></tr>`).join('')}</tbody></table></div></section>`;}
function finance(){const legacy=state.shipments.some(s=>s.status==='DELIVERED'&&s.cod_centimes>0&&!s.cod_collected&&!s.cod_receipt_state);return `<div class="note" style="margin-bottom:16px"><a class="btn" href="/merchant.html">↗ Espace comptabilité · Relevés & versements des marchands</a></div>${heading('Finance & COD','COD confirmé par rapprochement, relevés et versements marchands.',`<button class="btn" data-tab="cash">Ouvrir la caisse et les remises →</button>`)}<div class="card"><p class="note">Le journal est crédité après rapprochement des remises dans Caisse & remises. Les relevés marchands sont établis séparément ; un même COD ne peut pas être confirmé deux fois.</p>${legacy?'<details><summary>Régulariser une livraison historique sans déclaration de caisse</summary><p class="note">Réservé aux anciennes livraisons importées. Les colis avec un reçu de caisse passent obligatoirement par le rapprochement.</p><button class="btn outline" data-action="collect-cod">Confirmer un ancien encaissement</button></details>':''}<div class="divider"></div><h2>Journal des collectes</h2>${state.ledger.length?`<div class="table-scroll"><table class="table"><thead><tr><th>Commande</th><th>Type</th><th>Montant</th><th>Date</th></tr></thead><tbody>${state.ledger.map(l=>`<tr><td class="code">${esc(l.tracking)}</td><td>${esc(l.type)}</td><td>${money(l.amount_centimes)}</td><td>${date(l.created_at)}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">Aucune collecte confirmée.</div>`}</div>`;}
function tracking(){return `${heading('Suivi public','Page de consultation sans compte pour les destinataires.')}<div class="grid cols2"><section class="card"><h2>Rechercher un colis</h2><form id="tracking-form" class="form">${field('Numéro de suivi','tracking',{required:true,placeholder:'DN...'} )}<button class="btn" type="submit">⌕ Rechercher</button></form><div id="tracking-results"></div></section><section class="card"><h2>Confidentialité</h2><p class="muted">Le suivi ne révèle ni numéro de téléphone, ni adresse exacte, ni montant COD. Il présente la ville, le statut, et les événements de traitement.</p><div class="note">Le suivi est accessible avec le QR code du ticket ou le numéro du colis.</div></section></div>`;}
function renderDriver(){const me=state.me.user,rows=state.shipments;
 app.innerHTML=`<div class="driver-shell"><header class="driver-bar"><div><span class="tiny" style="color:#a8bddd">TRANSITFLOW · LIVREUR</span><h2 style="margin:7px 0 3px">Bonjour, ${esc(me.full_name.split(' ')[0])} 👋</h2><span class="tiny" style="color:#b7c8df">${esc(state.me.company.name)}</span></div><button class="btn outline small" data-action="logout">Sortir</button></header><div class="grid cols2" style="margin-top:20px"><div class="card metric"><span class="metric-label">Mes colis</span><span class="metric-value">${rows.length}</span></div><div class="card metric"><span class="metric-label">Livrés</span><span class="metric-value">${rows.filter(s=>s.status==='DELIVERED').length}</span></div></div><div class="section-title" style="margin:25px 0 15px"><h2>Mes livraisons</h2><button class="btn outline small" data-action="refresh">↻ Actualiser</button></div>${rows.length?rows.map(s=>`<article class="card driver-order"><div class="headline"><span class="code">${esc(s.tracking)}</span>${status(s.status)}</div><h3 style="margin-bottom:3px">${esc(s.recipient)}</h3><p>⌾ ${esc(s.city)} · ${esc(s.address)}</p><p>COD: <strong>${money(s.cod_centimes)}</strong></p><div class="driver-cta"><a class="btn outline" href="tel:${esc(s.phone.replace(/[^+0-9]/g,''))}">☎ Appeler</a><button class="btn outline" data-action="print-ticket" data-id="${s.id}">Ticket</button><button class="btn" data-action="driver-status" data-id="${s.id}">Changer statut</button></div></article>`).join(''):`<div class="card empty">Aucune commande affectée à votre compte.</div>`}<p class="tiny muted" style="text-align:center;margin-top:25px">Même site pour tous les rôles · aucun logiciel livreur séparé.</p></div>`;wire();
}
function modal(title,content){const previous=document.activeElement,div=document.createElement('div');div.className='modal-backdrop';div.innerHTML=`<div class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><div><span class="eyebrow">TRANSITFLOW · OPÉRATIONS</span><h2>${esc(title)}</h2></div><button class="close icon-button" data-action="close" aria-label="Fermer la fenêtre">${uiIcon('close')}</button></div>${content}</div>`;document.body.appendChild(div);const close=()=>{div.remove();previous?.focus();};div.addEventListener('click',e=>{if(e.target===div||e.target.closest('[data-action="close"]'))close();});div.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();close();}if(e.key==='Tab'){const items=[...div.querySelectorAll('button,input,select,textarea,a[href]')].filter(x=>!x.disabled&&x.getClientRects().length),first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});div.addEventListener('input',()=>div.querySelector('.form-error')?.remove());(div.querySelector('form input:not([type=hidden]),form select,form textarea')||div.querySelector('button'))?.focus();return div;}
async function action(a,el){
 if(await workflowAction(a,el))return;
 if(a==='close-menu'){document.querySelector('#nav')?.classList.remove('open');document.body.classList.remove('menu-open');return;}
 if(a==='copy-tracking'){const row=state.shipments.find(x=>x.id===el.dataset.id);if(row){await navigator.clipboard.writeText(row.tracking);toast('Tracking copié');}return;}
 if(a==='ship-status-chip'){state.status=el.dataset.value;state.shipPage=0;clearSelection();await refresh();return;}
 if(a==='ship-reset'){state.search='';state.status='';state.shipCity='';state.shipSource='';state.shipMerchant='';state.shipPage=0;clearSelection();await refresh();return;}
 if(a==='ship-clear-selection'){clearSelection();render();return;}
 if(a==='ship-export'){
  const rows=state.shipments.filter(s=>state.selectedIds.has(s.id));if(!rows.length)return;
  const cell=value=>{const text=String(value??'');return '"'+(/^[=+@\-\t\r]/.test(text)?"'"+text:text).replaceAll('"','""')+'"';};
  const data=[['Tracking','Marchand','Destinataire','Téléphone','Adresse','Ville','COD MAD','Statut'],...rows.map(s=>[s.tracking,s.merchant_name,s.recipient,s.phone,s.address,s.city,(s.cod_centimes/100).toFixed(2),state.me.statusLabels[s.status]||s.status])].map(row=>row.map(cell).join(';')).join('\r\n');
  const url=URL.createObjectURL(new Blob(['\ufeff'+data],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download='transitflow-colis-'+new Date().toISOString().slice(0,10)+'.csv';document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);toast(rows.length+' colis exporté(s)');return;
 }

 if(a==='ship-prev'||a==='ship-next'){state.shipPage+=a==='ship-next'?1:-1;await refresh();return;}
 if(a==='edit-user'){const u=state.users.find(x=>x.id===el.dataset.id);if(!u)return;const m=modal('Modifier le compte',`<form class="form">${field('Nom complet','name',{required:true,value:u.full_name})}${field('Téléphone','phone',{value:u.phone})}${field('Rôle','role',{options:Object.entries(state.me.roleLabels).map(([value,label])=>({value,label}))})}${field('Agence / hub','agencyId',{options:[{value:'',label:'Sans agence fixe'},...state.agencies.map(a=>({value:a.id,label:a.city}))]})}${field('Marchand (si compte client)','merchantId',{options:[{value:'',label:'Aucun'},...state.merchants.map(m=>({value:m.id,label:m.name}))]})}${field('Nouveau mot de passe (facultatif)','password',{type:'password'})}<label><input name="active" type="checkbox" ${u.active?'checked':''}> Compte actif</label><button class="btn" type="submit">Enregistrer le compte</button></form>`),form=m.querySelector('form');form.elements.role.value=u.role;form.elements.agencyId.value=u.agency_id||'';form.elements.merchantId.value=u.merchant_id||'';form.onsubmit=async e=>{e.preventDefault();try{const data=formData(form);data.active=form.elements.active.checked;await api('/users/'+u.id,{method:'PATCH',data});m.remove();toast('Compte mis à jour');await refresh();}catch(err){toast(err.message,true);}};return;}
 if(await operationAction(a,el))return;
 if(a==='logout'){await api('/auth/logout',{method:'POST',data:{}});state.me=null;state.selectedIds.clear();document.body.classList.remove('menu-open');authPage();return;}
 if(a==='menu'){$('#nav')?.classList.toggle('open');document.body.classList.toggle('menu-open');return;}
 if(a==='refresh'){await refresh();return;}
 if(a==='ship-actions'){
   const sh=state.shipments.find(s=>s.id===el.dataset.id);if(!sh)return;
   const m=modal(`Actions du colis — ${sh.tracking}`,shipmentMenuContent(sh));
   m.querySelectorAll('.menu-option').forEach(btn=>btn.addEventListener('click',()=>{m.remove();action(btn.dataset.action,btn).catch(e=>toast(e.message,true));}));return;
 }
 if(['history','info','edit-shipment','shipment-failed','change-cod','add-note','print-ticket'].includes(a)){
  const sh=state.shipments.find(s=>s.id===el.dataset.id);if(!sh)throw Error('Colis introuvable');
  if(a==='print-ticket'){
    await prepareLabels([sh.id]);return;
  }
  const detail=await api(`/shipments/${encodeURIComponent(sh.id)}`),s=detail.shipment;
  if(a==='history'){
    const events=detail.events.map(ev=>`<div class="event"><strong>${esc(state.me.statusLabels[ev.status]||ev.status)}</strong><small>${date(ev.created_at)} · ${esc(ev.source)}</small>${ev.note?`<p class="tiny muted">${esc(ev.note)}</p>`:''}</div>`).join('');
    modal(`Détails du suivi — ${s.tracking}`,`<div class="headline">${status(s.status)}<span class="tag">${esc(s.agency_name||s.driver_name||'Interne')}</span></div><div class="timeline">${events||'Aucun événement'}</div><div class="note">La livraison et le règlement du montant COD sont deux opérations indépendantes.</div>`);return;
  }
  if(a==='info'){
    const cells=[['Code',s.tracking],['Marchand',s.merchant_name||'—'],['Client',s.recipient],['Téléphone',s.phone],['Ville',s.city],['Adresse',s.address],['Marchandise',s.description||'—'],['Agence / livreur',s.agency_name||s.driver_name||'Interne'],['Montant COD',money(s.cod_centimes)],['Collecte COD',detail.codCollectionConfirmed?'Confirmée':'Non confirmée'],['Dernière mise à jour',date(s.updated_at)]];
    modal(`Information du colis — ${s.tracking}`,`<div class="info-list">${cells.map(([l,v])=>`<div><small>${esc(l)}</small><strong>${esc(v)}</strong></div>`).join('')}</div>${s.pending_agency_update?'<p class="note">Modification locale à transmettre au agence de destination. Pas de synchronisation du contenu garantie.</p>':''}${detail.notes.length?`<h3>Remarques internes</h3>${detail.notes.map(n=>`<p class="note">${esc(n.message)}<br><small>${esc(n.author)} · ${date(n.created_at)}</small></p>`).join('')}`:''}`);return;
  }
  if(a==='edit-shipment'){
    const fields=field('Destinataire','recipient',{required:true,value:s.recipient})+field('Téléphone','phone',{required:true,value:s.phone})+field('Ville','city',{required:true,value:s.city})+field('Adresse','address',{required:true,value:s.address})+field('Marchandise','description',{value:s.description})+field('Motif de modification','reason',{required:true,placeholder:'Justification obligatoire'});
    const m=modal(`Modifier le colis — ${s.tracking}`,`<form class="form">${fields}<p class="note">Si le colis a déjà été exporté, les modifications seront marquées à transmettre au agence de destination.</p><button class="btn" type="submit">Enregistrer</button></form>`);
    m.querySelector('form').onsubmit=async ev=>{ev.preventDefault();try{const result=await api(`/shipments/${s.id}`,{method:'PATCH',data:formData(ev.target)});m.remove();toast(result.pendingAgencyUpdate?'Modifié — à transmettre à l’agence':'Colis modifié');await refresh();}catch(err){toast(err.message,true);}};return;
  }
  if(a==='change-cod'){
    const m=modal(`Changer le prix — ${s.tracking}`,`<form class="form">${field('Nouveau montant COD (MAD)','cod',{type:'number',required:true,value:(s.cod_centimes/100).toFixed(2),min:0})}${field('Motif de changement','reason',{required:true,placeholder:'Justification obligatoire'})}<p class="note">Réservé aux administrateurs. La modification est auditée et ne marque jamais un montant comme encaissé.</p><button class="btn" type="submit">Confirmer le prix</button></form>`);
    m.querySelector('form').onsubmit=async ev=>{ev.preventDefault();try{const result=await api(`/shipments/${s.id}`,{method:'PATCH',data:formData(ev.target)});m.remove();toast(result.pendingAgencyUpdate?'Nouveau prix à transmettre à l’agence':'Prix modifié');await refresh();}catch(err){toast(err.message,true);}};return;
  }
  if(a==='shipment-failed'){
    const m=modal(`Colis non livré — ${s.tracking}`,`<form class="form">${field('Motif','status',{options:[{value:'POSTPONED',label:'Reporté — nouvelle tentative'},{value:'REFUSED',label:'Refusé par le destinataire'}]})}${field('Observation','note',{required:true,placeholder:'Précisez le motif constaté'})}<p class="note">Si la livraison est gérée par un partenaire externe, ses événements API restent la source officielle des mises à jour.</p><button class="btn" type="submit">Enregistrer le statut</button></form>`);
    m.querySelector('form').onsubmit=async ev=>{ev.preventDefault();try{await api(`/shipments/${s.id}/status`,{method:'POST',data:formData(ev.target)});m.remove();toast('Statut enregistré');await refresh();}catch(err){toast(err.message,true);}};return;
  }
  if(a==='add-note'){
    const m=modal(`Remarque — ${s.tracking}`,`<form class="form">${field('Commentaire interne','message',{required:true,placeholder:'Note opérationnelle'})}<button class="btn" type="submit">Ajouter la remarque</button></form>`);
    m.querySelector('form').onsubmit=async ev=>{ev.preventDefault();try{await api(`/shipments/${s.id}/notes`,{method:'POST',data:formData(ev.target)});m.remove();toast('Remarque ajoutée');}catch(err){toast(err.message,true);}};return;
  }
 }
 if(a==='new-shipment'){
  if(!state.cities.length){toast('Ajoutez d’abord une ville dans Agences & hubs',true);return;}
  const merchant=state.me.user.role==='MERCHANT';
  const fields=`<div class="order-intro"><span>${uiIcon('shipments')}</span><div><strong>Une nouvelle expédition</strong><p>Choisissez l’origine du colis et renseignez son destinataire.</p></div></div><fieldset class="form-section"><legend><b>01</b> Origine de la commande</legend><div class="form-grid">${field('Type de commande','source',{options:[{value:'EXTERNAL',label:'Commande ramassage — colis chez le marchand'},{value:'STOCK',label:'Commande stock — produits au warehouse'}]})}${!merchant?field('Marchand propriétaire','merchantId',{options:[{value:'',label:'Sélectionner un marchand'},...state.merchants.map(m=>({value:m.id,label:m.name}))]}):''}</div><div id="order-stock-fields" hidden><p class="field-help">Sélectionnez les produits du marchand. Les quantités sont réservées à la création.</p>${stockLinesMarkup()}</div></fieldset><fieldset class="form-section"><legend><b>02</b> Destinataire & livraison</legend><div class="form-grid">${field('Nom complet du destinataire','recipient',{required:true,placeholder:'Ex. Salma El Idrissi'})}${field('Téléphone','phone',{type:'tel',required:true,placeholder:'06 00 00 00 00'})}${field('Ville de destination','city',{options:state.cities.map(city=>({value:city,label:city})),required:true})}${field('Secteur / quartier','sector',{placeholder:'Ex. Centre-ville'})}<div class="span-2">${field('Adresse complète','address',{required:true,placeholder:'Rue, numéro, immeuble et indications utiles'})}</div></div></fieldset><fieldset class="form-section"><legend><b>03</b> Contenu & encaissement</legend><div class="form-grid">${field('Montant à encaisser (MAD)','cod',{type:'number',value:0,min:0,step:'0.01'})}${field('Description du colis','description',{placeholder:'Ex. 2 articles cosmétiques'})}</div><div class="order-options"><label><input type="checkbox" name="fragile"><span>Colis fragile<small>Manipuler avec précaution</small></span></label><label><input type="checkbox" name="allowOpen"><span>Ouverture autorisée<small>Avant paiement, selon vos consignes</small></span></label></div></fieldset>`;
  const m=modal('Nouvelle commande',`<form class="form order-form"><div class="order-form-body">${fields}</div><div class="form-footer"><span>La destination détermine automatiquement l’agence.</span><button class="btn" type="submit">${uiIcon('plus')}Créer la commande</button></div></form>`),form=m.querySelector('form');
  if(el?.dataset?.source)form.elements.source.value=el.dataset.source;
  const lines=wireStockLines(form,()=>state.inventory.filter(p=>p.merchant_id===(merchant?state.me.user.merchant_id:form.elements.merchantId.value||null)));const sync=()=>{m.querySelector('#order-stock-fields').hidden=form.elements.source.value!=='STOCK';lines.sync();};form.elements.source.addEventListener('change',sync);sync();
  if(!merchant)form.elements.merchantId.onchange=()=>lines.reset();
  form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('button[type="submit"]');button.disabled=true;try{const data=formData(form);data.fragile=form.elements.fragile.checked;data.allowOpen=form.elements.allowOpen.checked;if(data.source==='STOCK')data.items=readStockLines(form);delete data.productId;delete data.quantity;const result=await api('/shipments',{method:'POST',data});m.remove();toast(`Colis ${result.tracking} créé`);await refresh();}catch(err){toast(err.message,true);button.disabled=false;}};return;
 }
 if(a==='new-product'){
  const m=modal('Nouveau produit',`<form class="form">${field('SKU','sku',{required:true,placeholder:'SERUM-30ML'})}${field('Nom produit','name',{required:true})}${field('Code-barres produit (facultatif)','barcode')}${field('Seuil d’alerte','lowStockThreshold',{type:'number',min:0,value:0})}${field('Marchand propriétaire','merchantId',{options:[{value:'',label:'Non attribué'},...state.merchants.map(m=>({value:m.id,label:m.name}))]})}<button class="btn" type="submit">Créer le produit</button></form>`);
  m.querySelector('form').onsubmit=async e=>{e.preventDefault();try{await api('/inventory/products',{method:'POST',data:formData(e.target)});m.remove();toast('Produit créé');await refresh();}catch(err){toast(err.message,true);}};return;
 }
 if(a==='receive-stock'||a==='reserve-stock'){
  const isReceive=a==='receive-stock',isReserve=a==='reserve-stock';
  const opts=state.inventory.map(p=>({value:p.id,label:`${p.sku} — ${p.name} (disponible ${p.available})`}));
  const ships=state.shipments.map(s=>({value:s.id,label:`${s.tracking} · ${s.city}`}));
  const fields=`${field('Produit','productId',{options:opts})}${isReserve?field('Commande','shipmentId',{options:ships}):field('Emplacement','location',{value:'ENTREPOT'})}${field('Quantité','quantity',{type:'number',min:1,required:true,value:1})}`;
  const m=modal(isReceive?'Réception de stock':'Réservation FIFO',`<form class="form">${fields}<button class="btn" type="submit">Confirmer</button></form>`);
  m.querySelector('form').onsubmit=async e=>{e.preventDefault();try{await api(isReceive?'/inventory/receive':'/inventory/reserve',{method:'POST',data:formData(e.target)});m.remove();toast('Mouvement de stock enregistré');await refresh();}catch(err){toast(err.message,true);}};return;
 }
 if(a==='new-merchant'){
  const m=modal('Nouveau marchand',`<form class="form">${field('Nom du marchand','name',{required:true})}${field('Téléphone','phone')}<button class="btn" type="submit">Créer le marchand</button></form>`);
  m.querySelector('form').onsubmit=async e=>{e.preventDefault();try{await api('/merchants',{method:'POST',data:formData(e.target)});m.remove();toast('Marchand créé');await refresh();}catch(err){toast(err.message,true);}};return;
 }
 if(a==='assign'){
  const sh=state.shipments.find(x=>x.id===el.dataset.id);if(!sh)return;
  const drivers=state.users.filter(u=>u.role==='DRIVER'&&u.active),m=modal(`Livreur du colis ${sh.tracking}`,`<form class="form"><p class="note">Agence : ${esc(sh.agency_name)} · ${esc(sh.city)}</p>${field('Livreur interne','driverId',{options:[{value:'',label:'Sans livreur interne'},...drivers.map(d=>({value:d.id,label:d.full_name}))]})}<button class="btn" type="submit">Enregistrer</button></form>`);
  m.querySelector('form').onsubmit=async e=>{e.preventDefault();try{await api('/shipments/assign',{method:'POST',data:{shipmentId:sh.id,...formData(e.target)}});m.remove();toast('Livreur affecté');await refresh();}catch(err){toast(err.message,true);}};return;
 }
 if(a==='new-user'){
  const m=modal('Créer un utilisateur',`<form class="form">${field('Nom complet','name',{required:true})}${field('Email','email',{type:'email',required:true})}${field('Rôle','role',{options:Object.entries(state.me.roleLabels).map(([value,label])=>({value,label}))})}${field('Agence / hub (obligatoire pour un agent agence)','agencyId',{options:[{value:'',label:'Sans agence fixe'},...state.agencies.map(a=>({value:a.id,label:a.city+' · '+a.name}))]})}${field('Téléphone','phone')}${field('Marchand (si rôle MERCHANT)','merchantId',{options:[{value:'',label:'Aucun'},...state.merchants.map(x=>({value:x.id,label:x.name}))]})}${field('Mot de passe temporaire (12 caractères minimum)','password',{type:'password',required:true})}<button class="btn" type="submit">Créer le compte</button></form>`);
  m.querySelector('form').onsubmit=async e=>{e.preventDefault();try{await api('/users',{method:'POST',data:formData(e.target)});m.remove();toast('Utilisateur créé');await refresh();}catch(err){toast(err.message,true);}};return;
 }
 if(a==='driver-status'){
  const sh=state.shipments.find(s=>s.id===el.dataset.id);if(!sh)return;
  const choices=['OUT_FOR_DELIVERY','DELIVERED','POSTPONED','REFUSED'].filter(v=>v!==sh.status);
  const m=modal(`Statut colis ${sh.tracking}`,`<form class="form">${field('Nouveau statut','status',{options:choices.map(x=>({value:x,label:state.me.statusLabels[x]}))})}${field('Motif / commentaire','note')}<button class="btn" type="submit">Enregistrer</button></form>`);
  m.querySelector('form').onsubmit=async e=>{e.preventDefault();try{await api(`/shipments/${sh.id}/status`,{method:'POST',data:formData(e.target)});m.remove();toast('Statut mis à jour');await refresh();}catch(err){toast(err.message,true);}};return;
 }
 if(a==='collect-cod'){
  const eligible=state.shipments.filter(s=>s.status==='DELIVERED'&&s.cod_centimes>0&&!s.cod_collected&&!s.cod_receipt_state);
  const m=modal('Confirmer une collecte COD',`<form class="form">${field('Commande livrée','shipmentId',{options:eligible.map(s=>({value:s.id,label:`${s.tracking} · ${money(s.cod_centimes)}`}))})}<p class="note">À utiliser uniquement après avoir vérifié l'encaissement réel. Cette action ne correspond pas au versement au marchand.</p><button class="btn" ${eligible.length?'':'disabled'} type="submit">Confirmer la collecte</button></form>`);
  m.querySelector('form').onsubmit=async e=>{e.preventDefault();try{await api('/ledger/collect',{method:'POST',data:formData(e.target)});m.remove();toast('Collecte enregistrée');await refresh();}catch(err){toast(err.message,true);}};return;
 }
}
function wire(){
 wireWorkflows();wireOperations();
 document.querySelectorAll('[data-tab]').forEach(e=>e.addEventListener('click',async()=>{if(e.dataset.search){state.search=e.dataset.search;state.status='';state.shipCity='';state.shipSource='';state.shipMerchant='';state.shipPage=0;}if(e.dataset.city){state.shipCity=e.dataset.city;state.search='';state.status='';state.shipSource='';state.shipMerchant='';state.shipPage=0;}document.body.classList.remove('menu-open');try{await navigate(e.dataset.tab);}catch(err){toast(err.message,true);}}));
 document.querySelectorAll('[data-action]').forEach(e=>e.addEventListener('click',()=>action(e.dataset.action,e).catch(err=>toast(err.message,true))));
 $('#ship-search')?.addEventListener('input',e=>{state.search=e.target.value;state.shipPage=0;clearSelection();clearTimeout(shipSearchTimer);shipSearchTimer=setTimeout(()=>refresh().then(()=>{$('#ship-search')?.focus();$('#ship-search')?.setSelectionRange(state.search.length,state.search.length);}).catch(err=>toast(err.message,true)),250);});
 for(const [id,key] of [['ship-status','status'],['ship-city','shipCity'],['ship-source','shipSource'],['ship-merchant','shipMerchant'],['ship-sort','shipSort'],['ship-page-size','shipPageSize']])$('#'+id)?.addEventListener('change',e=>{state[key]=key==='shipPageSize'?Number(e.target.value):e.target.value;state.shipPage=0;clearSelection();refresh().catch(err=>toast(err.message,true));});
 const selectionChanged=()=>{const selected=state.selectedIds;document.querySelectorAll('[data-select-shipment]').forEach(input=>{input.checked=selected.has(input.dataset.selectShipment);input.closest('tr,.shipment-card')?.classList.toggle('selected',input.checked);});const bar=document.querySelector('.selection-bar');if(bar){bar.hidden=!selected.size;bar.querySelector('[data-selected-count]').textContent=selected.size;}const all=document.querySelector('#ship-select-all');if(all){all.checked=state.shipments.length>0&&state.shipments.every(s=>selected.has(s.id));all.indeterminate=selected.size>0&&!all.checked;}};
 document.querySelectorAll('[data-select-shipment]').forEach(input=>input.addEventListener('change',()=>{input.checked?state.selectedIds.add(input.dataset.selectShipment):state.selectedIds.delete(input.dataset.selectShipment);selectionChanged();}));
 $('#ship-select-all')?.addEventListener('change',e=>{e.target.checked?state.shipments.forEach(s=>state.selectedIds.add(s.id)):state.selectedIds.clear();selectionChanged();});
 $('#global-search')?.addEventListener('submit',e=>{e.preventDefault();state.search=e.target.elements.q.value.trim();state.status='';state.shipCity='';state.shipSource='';state.shipMerchant='';state.shipPage=0;navigate('shipments').catch(error=>toast(error.message,true));});
 $('#import-form')?.addEventListener('submit',async e=>{e.preventDefault();const file=$('#import-file').files[0];if(!file)return;const result=$('#import-result');if(file.size>4_000_000){result.textContent='Maximum 4 Mo';return;}try{const bytes=await file.arrayBuffer();const data=await api('/import/orders',{method:'POST',raw:bytes,contentType:file.name.toLowerCase().endsWith('.csv')?'text/csv':'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'});result.textContent=`Import terminé : ${data.inserted} commandes, ${data.skipped} ignorées. ${data.errors.slice(0,4).map(x=>`Ligne ${x.line}: ${x.error}`).join(' · ')}`;toast('Import terminé');}catch(err){result.textContent=err.message;toast(err.message,true);}});
 $('#tracking-form')?.addEventListener('submit',async e=>{e.preventDefault();const id=e.target.elements.tracking.value;const div=$('#tracking-results');try{const res=await api(`/tracking/${encodeURIComponent(id)}`);div.innerHTML=`<div class="divider"></div><div class="headline"><strong class="code">${esc(res.tracking)}</strong><span class="pill ${esc(res.status)}">${esc(res.statusLabel)}</span></div><p>Ville: <strong>${esc(res.city)}</strong> · Actualisé: ${date(res.updatedAt)}</p><div class="timeline">${res.events.map(ev=>`<div class="event"><strong>${esc(state.me?.statusLabels?.[ev.status]||ev.status)}</strong><small>${date(ev.created_at)}</small></div>`).join('')}</div>`;}catch(err){div.innerHTML=`<p class="error">${esc(err.message)}</p>`;}});
}
configureWorkflows({createOrder:source=>action('new-shipment',{dataset:{source}}),state,api,esc,money,date,status,field,formData,modal,toast,refresh,heading,render,navigate,availableTabs});
configureOperations({state,api,esc,money,date,status,field,formData,modal,toast,refresh,heading,render});
window.addEventListener('popstate',()=>{if(state.me)load();});
window.addEventListener('keydown',event=>{if(event.key==='Escape'&&document.body.classList.contains('menu-open')){$('#nav')?.classList.remove('open');document.body.classList.remove('menu-open');$('.mobile-menu')?.focus();}});
load();
